const body = pm.response.json();

pm.test("HTTP status is 200", () => {
    pm.response.to.have.status(200);
});

pm.test("responseCode in body is 200", () => {
    pm.expect(body.responseCode).to.eql(200);
});

pm.test("product list is not empty", () => {
    pm.expect(body.products).to.be.an("array").that.is.not.empty;
});

pm.test("Content-Type header is present and is text/html", () => {
    pm.response.to.have.header("Content-Type");
    pm.expect(pm.response.headers.get("Content-Type")).to.include("text/html");
});

pm.test("first product has id, name, price, brand and category", () => {
    pm.expect(body.products[0]).to.have.all.keys("id", "name", "price", "brand", "category");
});

